export function loadUser(api, id) {
  return api.get('/users/' + id)
    .then((r) => r.json())
    .then((u) => {
      if (!u.active) throw new Error('inactive user');
      return api.get('/teams/' + u.team).then((r) => r.json()).then((t) => ({ ...u, team: t }));
    })
    .catch((e) => {
      console.warn('loadUser failed', e);
      return null;
    });
}

export function loadAll(api, ids) {
  return Promise.all(ids.map((id) => loadUser(api, id))).then((list) => list.filter(Boolean));
}
